// Image, pixel data stored in CPU memory (RAM)
type Image struct {
	Data    unsafe.Pointer // data
	Width   int32          // width
	Height  int32          // height
	Mipmaps int32          // mipmaps
	Format  int32          // format
}

// Material is the C struct Material.
//
// Material, includes shader and maps
type Material struct {
	Shader Shader       // shader
	Maps   *MaterialMap // maps
	Params [4]float32   // params
}

// Shader is the C struct Shader.
//
// Shader
type Shader struct {
	Id   uint32 // id
	Locs *int32 // locs
}

// MaterialMap is the C struct MaterialMap.
//
// MaterialMap
type MaterialMap struct {
	Texture Texture // texture
	Color   Color   // color
	Value   float32 // value
}

// Matrix is the C struct Matrix.
//
// Matrix, 4x4 components, column major, OpenGL style, right-handed
type Matrix struct {
	M0  float32 // m0
	M4  float32 // m4
	M8  float32 // m8
	M12 float32 // m12
	M1  float32 // m1
	M5  float32 // m5
	M9  float32 // m9
	M13 float32 // m13
	M2  float32 // m2
	M6  float32 // m6
	M10 float32 // m10
	M14 float32 // m14
	M3  float32 // m3
	M7  float32 // m7
	M11 float32 // m11
	M15 float32 // m15
}

// Mesh is the C struct Mesh.
//
// Mesh, vertex data and vao/vbo
type Mesh struct {
	VertexCount   int32    // vertexCount
	TriangleCount int32    // triangleCount
	Vertices      *float32 // vertices
	Texcoords     *float32 // texcoords
	Texcoords2    *float32 // texcoords2
	Normals       *float32 // normals
	Tangents      *float32 // tangents
	Colors        *uint8   // colors
	Indices       *uint16  // indices
	BoneCount     int32    // boneCount
	BoneIndices   *uint8   // boneIndices
	BoneWeights   *float32 // boneWeights
	AnimVertices  *float32 // animVertices
	AnimNormals   *float32 // animNormals
	VaoId         uint32   // vaoId
	VboId         *uint32  // vboId
}

// Model is the C struct Model.
//
// Model, meshes, materials and animation data
type Model struct {
	Transform     Matrix        // transform
	MeshCount     int32         // meshCount
	MaterialCount int32         // materialCount
	Meshes        *Mesh         // meshes
	Materials     *Material     // materials
	MeshMaterial  *int32        // meshMaterial
	Skeleton      ModelSkeleton // skeleton
	CurrentPose   *Transform    // currentPose
	BoneMatrices  *Matrix       // boneMatrices
}

// ModelSkeleton is the C struct ModelSkeleton.
//
// Skeleton, animation bones hierarchy
type ModelSkeleton struct {
	BoneCount uint32     // boneCount
	Bones     *BoneInfo  // bones
	BindPose  *Transform // bindPose
}

// BoneInfo is the C struct BoneInfo.
//
// Bone, skeletal animation bone
type BoneInfo struct {
	Name   [32]byte // name
	Parent int32    // parent
}

// Transform is the C struct Transform.
//
// Transform, vertex transformation data
type Transform struct {
	Translation Vector3 // translation
	Rotation    Vector4 // rotation
	Scale       Vector3 // scale
}

// Vector4 is the C struct Vector4.
//
// Vector4, 4 components
type Vector4 struct {
	X float32 // x
	Y float32 // y
	Z float32 // z
	W float32 // w
}

// ModelAnimation is the C struct ModelAnimation.
//
// ModelAnimation, contains a full animation sequence
type ModelAnimation struct {
	Name          [32]byte       // name
	BoneCount     uint32         // boneCount
	KeyframeCount int32          // keyframeCount
	KeyframePoses unsafe.Pointer // keyframePoses
}

// Music is the C struct Music.
//
// Music, audio stream, anything longer than ~10 seconds should be streamed
type Music struct {
	Stream     AudioStream    // stream
	FrameCount uint32         // frameCount
	Looping    bool           // looping
	CtxType    int32          // ctxType
	CtxData    unsafe.Pointer // ctxData
}

// NPatchInfo is the C struct NPatchInfo.
//
// NPatchInfo, n-patch layout info
type NPatchInfo struct {
	Source Rectangle // source
	Left   int32     // left
	Top    int32     // top
	Right  int32     // right
	Bottom int32     // bottom
	Layout int32     // layout
}

// Ray is the C struct Ray.
//
// Ray, ray for raycasting
type Ray struct {
	Position  Vector3 // position
	Direction Vector3 // direction
}

// RayCollision is the C struct RayCollision.
//
// RayCollision, ray hit information
type RayCollision struct {
	Hit      bool    // hit
	Distance float32 // distance
	Point    Vector3 // point
	Normal   Vector3 // normal
}

// Sound is the C struct Sound.
//
// Sound
type Sound struct {
	Stream     AudioStream // stream
	FrameCount uint32      // frameCount
}

// VrDeviceInfo is the C struct VrDeviceInfo.
//
// VrDeviceInfo, Head-Mounted-Display device parameters
type VrDeviceInfo struct {
	HResolution            int32      // hResolution
	VResolution            int32      // vResolution
	HScreenSize            float32    // hScreenSize
	VScreenSize            float32    // vScreenSize
	EyeToScreenDistance    float32    // eyeToScreenDistance
	LensSeparationDistance float32    // lensSeparationDistance
	InterpupillaryDistance float32    // interpupillaryDistance
	LensDistortionValues   [4]float32 // lensDistortionValues
	ChromaAbCorrection     [4]float32 // chromaAbCorrection
}

// VrStereoConfig is the C struct VrStereoConfig.
//
// VrStereoConfig, VR stereo rendering configuration for simulator
type VrStereoConfig struct {
	Projection        [2]Matrix  // projection
	ViewOffset        [2]Matrix  // viewOffset
	LeftLensCenter    [2]float32 // leftLensCenter
	RightLensCenter   [2]float32 // rightLensCenter
	LeftScreenCenter  [2]float32 // leftScreenCenter
	RightScreenCenter [2]float32 // rightScreenCenter
	Scale             [2]float32 // scale
	ScaleIn           [2]float32 // scaleIn
}

// Wave is the C struct Wave.
//
// Wave, audio wave data
type Wave struct {
	FrameCount uint32         // frameCount
	SampleRate uint32         // sampleRate
	SampleSize uint32         // sampleSize
	Channels   uint32         // channels
	Data       unsafe.Pointer // data
}

// Camera is Camera3D.
type Camera = Camera3D

// RenderTexture2D is RenderTexture.
type RenderTexture2D = RenderTexture

// RenderTexture is the C struct RenderTexture.
//
// RenderTexture, fbo for texture rendering
type RenderTexture struct {
	Id      uint32  // id
	Texture Texture // texture
	Depth   Texture // depth
}

// Texture2D is Texture.
type Texture2D = Texture

// TextureCubemap is Texture.
type TextureCubemap = Texture

