// Resume audio stream
func ResumeAudioStream(stream AudioStream) {
	C.ResumeAudioStream(*(*C.AudioStream)(unsafe.Pointer(&stream)))
}

// IsAudioStreamPlaying calls IsAudioStreamPlaying.
//
// Check if audio stream is playing
func IsAudioStreamPlaying(stream AudioStream) bool {
	r := C.IsAudioStreamPlaying(*(*C.AudioStream)(unsafe.Pointer(&stream)))
	return bool(r)
}

// StopAudioStream calls StopAudioStream.
//
// Stop audio stream
func StopAudioStream(stream AudioStream) {
	C.StopAudioStream(*(*C.AudioStream)(unsafe.Pointer(&stream)))
}

// SetAudioStreamVolume calls SetAudioStreamVolume.
//
// Set volume for audio stream (1.0 is max level)
func SetAudioStreamVolume(stream AudioStream, volume float32) {
	C.SetAudioStreamVolume(*(*C.AudioStream)(unsafe.Pointer(&stream)), C.float(volume))
}

// SetAudioStreamPitch calls SetAudioStreamPitch.
//
// Set pitch for audio stream (1.0 is base level)
func SetAudioStreamPitch(stream AudioStream, pitch float32) {
	C.SetAudioStreamPitch(*(*C.AudioStream)(unsafe.Pointer(&stream)), C.float(pitch))
}

// SetAudioStreamPan calls SetAudioStreamPan.
//
// Set pan for audio stream (-1.0 left, 0.0 center, 1.0 right)
func SetAudioStreamPan(stream AudioStream, pan float32) {
	C.SetAudioStreamPan(*(*C.AudioStream)(unsafe.Pointer(&stream)), C.float(pan))
}

// SetAudioStreamBufferSizeDefault calls SetAudioStreamBufferSizeDefault.
//
// Default size for new audio streams
func SetAudioStreamBufferSizeDefault(size int) {
	C.SetAudioStreamBufferSizeDefault(C.int(size))
}
